package repoid

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// CatalogFile is a machine's repository catalog as the store carries it,
// generated by code: in the store, inbox/dreamer@<host>/_repos.json (the one
// place a machine's dreamer may write, so no two machines write one file);
// on a machine with the local layer, the same path in its overlay, which
// never leaves the machine. The name starts with an underscore, which no
// fact's name can, and is no .md file: no fact walk, search index, tree
// index or hook reads it as a fact.
//
// It lists the repositories the machine has a checkout of (Catalog.Shared):
// each one's name, its aliases and its remotes' normalized URLs. No local
// path and no user name is in it (NormURL drops a URL's user and password,
// and a remote on the file system has no URL). The metadata checks on every
// machine read every machine's (Catalog.AddShared), so a note about a
// repository checked out only on another machine names a known repository.
const CatalogFile = "_repos.json"

// SharedRepo is one repository of a machine's shared catalog.
type SharedRepo struct {
	Name    string   `json:"name"`
	Aliases []string `json:"aliases,omitempty"`
	URLs    []string `json:"urls,omitempty"`
	// WorkSessions is how many sessions worked in the checkout (edits or
	// commits there), with the first and last day: for a checkout outside
	// home or in a temp directory, the evidence it is in the catalog on;
	// for every checkout, what an assessment of the project reads.
	WorkSessions int    `json:"work_sessions,omitempty"`
	FirstWork    string `json:"first_work,omitempty"`
	LastWork     string `json:"last_work,omitempty"`
	// OwnCommits are the commits under the machine's git identity, with the
	// first and last commit day (Commits); absent when git could not say.
	OwnCommits  *int   `json:"own_commits,omitempty"`
	FirstCommit string `json:"first_commit,omitempty"`
	LastCommit  string `json:"last_commit,omitempty"`
}

type sharedFile struct {
	Generated string       `json:"generated"`
	Repos     []SharedRepo `json:"repos"`
}

const sharedNote = "by tacit from this machine's checkouts; never edited by hand"

// Shared is the catalog's own repositories (those with a checkout on this
// machine, not those another machine's catalog added) as CatalogFile's
// bytes, sorted, so an unchanged catalog writes the same bytes.
func (c *Catalog) Shared() []byte { return c.SharedWith(nil) }

// SharedWith is Shared with each checkout's commit evidence from commits
// (nil: none; a false ok leaves it out).
func (c *Catalog) SharedWith(commits func(root string) (Commits, bool)) []byte {
	f := sharedFile{Generated: sharedNote, Repos: []SharedRepo{}}
	for _, slug := range c.Names() {
		r := c.repos[slug]
		if r.Root == "" {
			continue
		}
		e := SharedRepo{Name: slug, URLs: r.URLs}
		for _, a := range r.Aliases {
			if Slug(a) != "" {
				e.Aliases = append(e.Aliases, a)
			}
		}
		e.WorkSessions, e.FirstWork, e.LastWork = WorkSummary(c.work[r.Root])
		if commits != nil {
			if cm, ok := commits(r.Root); ok {
				n := cm.Own
				e.OwnCommits, e.FirstCommit, e.LastCommit = &n, cm.First, cm.Last
			}
		}
		f.Repos = append(f.Repos, e)
	}
	b, _ := json.MarshalIndent(f, "", " ")
	return append(b, '\n')
}

// AddShared adds the repositories of a shared catalog (CatalogFile's bytes)
// that the catalog does not hold yet, as known names with no checkout here;
// it reports whether b parsed. A repository this machine has keeps its own
// entry (the other machine's aliases join it).
func (c *Catalog) AddShared(b []byte) bool {
	var f sharedFile
	if err := json.NewDecoder(bytes.NewReader(b)).Decode(&f); err != nil {
		return false
	}
	for _, e := range f.Repos {
		slug := Slug(e.Name)
		if slug == "" {
			continue
		}
		r := Repo{Name: slug}
		for _, a := range e.Aliases {
			if Slug(a) != "" {
				r.Aliases = addAlias(r.Aliases, slug, a)
			}
		}
		for _, u := range e.URLs {
			r.URLs = addURL(r.URLs, u)
		}
		c.add(r)
	}
	return true
}

// AddSharedFile is AddShared for the file at path; a missing or unreadable
// file adds nothing.
func (c *Catalog) AddSharedFile(path string) {
	if b, err := os.ReadFile(path); err == nil {
		c.AddShared(b)
	}
}

// AddStoreCatalogs adds every machine's shared catalog in the store at dir
// (inbox/*/CatalogFile), in path order.
func (c *Catalog) AddStoreCatalogs(dir string) {
	if dir == "" {
		return
	}
	paths, _ := filepath.Glob(filepath.Join(dir, "inbox", "*", CatalogFile))
	sort.Strings(paths)
	for _, p := range paths {
		c.AddSharedFile(p)
	}
}

// HostRepo is one machine's entry for a repository in the store's shared
// catalogs: the writing machine (its inbox folder's host) and what its
// catalog says.
type HostRepo struct {
	Host string
	SharedRepo
}

// StoreEvidence reads every machine's shared catalog in the store at dir
// (inbox/<writer>@<host>/CatalogFile): repository name -> each machine's
// entry, in host order.
func StoreEvidence(dir string) map[string][]HostRepo {
	out := map[string][]HostRepo{}
	if dir == "" {
		return out
	}
	paths, _ := filepath.Glob(filepath.Join(dir, "inbox", "*", CatalogFile))
	sort.Strings(paths)
	for _, p := range paths {
		_, host, _ := strings.Cut(filepath.Base(filepath.Dir(p)), "@")
		b, err := os.ReadFile(p)
		if err != nil {
			continue
		}
		var f sharedFile
		if json.NewDecoder(bytes.NewReader(b)).Decode(&f) != nil {
			continue
		}
		for _, e := range f.Repos {
			if s := Slug(e.Name); s != "" {
				out[s] = append(out[s], HostRepo{Host: host, SharedRepo: e})
			}
		}
	}
	return out
}
